SM = yaml.safe_load(open('governance/stage-map.yaml'))['tables']
def stage(v): return v if isinstance(v,str) else v.get('stage')
base = sorted(t for t,v in SM.items() if stage(v)=='base')
print('base tables:', len(base))
def fks(dbpath, label):
    con = sqlite3.connect(f'file:{dbpath}?mode=ro', uri=True)
    live = {r[0] for r in con.execute("select name from sqlite_master where type='table'")}
    print(label, 'base tables absent from schema:', [t for t in base if t not in live])
    for t in base:
        if t not in live: continue
        for f in con.execute(f'pragma foreign_key_list("{t}")'):
            s = stage(SM.get(f[2], '?UNMAPPED'))
            if s != 'base': print(f'  {label} {t}.{f[3]} -> {f[2]}.{f[4]} [{s}]')
    print(label, 'base_parameters fks:', [(f[3],f[2]) for f in con.execute('pragma foreign_key_list(base_parameters)')])
    print([ (r[1],r[2],r[3]) for r in con.execute('pragma table_info(base_parameters)')])
    print('kinded:', con.execute('select count(*), sum(quantity_kind is not null) from base_parameters').fetchall())
    for typ,name,sql in con.execute("select type,name,sql from sqlite_master where sql like '%base_parameters%' and name<>'base_parameters'"):
        if typ in ('view','trigger'):
            try:
                if typ=='view': con.execute(f'select * from "{name}" limit 1').fetchall()
                ok='ok'
            except Exception as e: ok='BROKEN '+str(e)
            print('   ',typ,name,ok, con.execute(f'select count(*) from "{name}"').fetchone()[0] if typ=='view' and ok=='ok' else '')
        elif typ=='index': print('    index',name)
